#include "emergency.hpp"
namespace exotic::runtime {EmergencyCoordinator::EmergencyCoordinator(autonomy::governance::GovernanceService&g,autonomy::governance::GovernanceRepository&r,autonomy::resources::ResourceGovernor&res,AuditTimeline&a):governance_(g),governance_repo_(r),resources_(res),audit_(a){}void EmergencyCoordinator::activate(std::string_view actor,std::string_view reason){governance_.emergency_stop(actor,reason);resources_.emergency_stop(actor,reason);audit_.emit("control",std::string{actor},"runtime","global","Emergency stop activated","{\"reason\":\""+std::string{reason}+"\"}");}void EmergencyCoordinator::clear(std::string_view actor,std::string_view reason){governance_.clear_emergency_stop(actor,reason);resources_.clear_emergency_stop(actor,reason);audit_.emit("control",std::string{actor},"runtime","global","Emergency stop cleared","{\"reason\":\""+std::string{reason}+"\"}");}bool EmergencyCoordinator::active(){return governance_repo_.emergency_stop_active()||resources_.status().emergency_stop;}}
